# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİİLDE (EYLEMDE) ÇATI — ÖZNESİNE GÖRE FİİLLER (T.8.4.19)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Etken Çatılı Fiiller (Gerçek / Gizli Özne)</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#334155">• İşi yapan özne bellidir; \'-l, -n\' çatı eki almaz.</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">Örnek: "Fırıncı sıcak ekmekleri sepete dizdi."</text>\n  <text x="180" y="132" text-anchor="middle" font-size="11" fill="#334155">(Dizen kim? ➔ Fırıncı — Gerçek Özne)</text>\n  <text x="180" y="158" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Edilgen Çatılı Fiiller (Sözde Özne)</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#334155">• Fiil \'-l\' veya \'-n\' eki alır; işi kimin yaptığı belli değildir.</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" fill="#334155">• İşten etkilenen nesne \'Sözde Özne\' olur (\'başkası tarafından\').</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Örnek: "Sıcak ekmekler sepete diz-il-di." (Sözde özne)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. Dönüşlü ve 4. İşteş Çatı (Tamamlayıcı Bilgi)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• Dönüşlü Fiil (\'-l, -n\' eki + Gerçek Özne):</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" fill="#334155">Özne işi hem kendi yapar hem de işten kendi etkilenir.</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Örnek: "Çocuk sınavı kazanınca çok sev-in-di."</text>\n  <text x="520" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">• İşteş Fiil (\'-ş\' eki + Birlikte / Karşılıklı):</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11" fill="#334155">Eylem birden fazla özne tarafından birlikte veya</text>\n  <text x="520" y="194" text-anchor="middle" font-size="11" fill="#334155">karşılıklı yapılır: "Kuşlar uç-uş-tu." / "Arkadaşlar selamla-ş-tı."</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#dc2626">DİKKAT: İsim cümlelerinde çatı özelliği ARANMAZ!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİİLDE ÇATI — NESNESİNE GÖRE FİİLLER (GEÇİŞLİ VE GEÇİŞSİZ)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Geçişli Fiiller (Nesne Alabilen)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• "Neyi, Kimi, Ne?" sorularına cevap verir.</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• Başına "Onu" zamiri getirildiğinde anlamlı olur:</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#334155">(Onu) okudu ✓ | (Onu) paylaştı ✓ | (Onu) anladı ✓</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">Önemli Not:</text>\n  <text x="180" y="184" text-anchor="middle" font-size="11" fill="#334155">"Dedem akşam erkenden okudu." cümlesinde</text>\n  <text x="180" y="202" text-anchor="middle" font-size="11" fill="#334155">nesne yazılmasa bile "(Onu) okudu" diyebildiğimiz</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">için "okudu" fiili yine GEÇİŞLİDİR!</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">2. Geçişsiz Fiiller (Nesne Alamayan)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• "Neyi, Kimi, Ne?" sorularına cevap vermez.</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Başına "Onu" zamiri getirildiğinde anlamsız olur:</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#334155">(Onu) uyudu ✗ | (Onu) güldü ✗ | (Onu) oturdu ✗</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#881337">Örnekler:</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11" fill="#334155">"Küçük çocuk mışıl mışıl uyudu." ➔ Geçişsiz</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" fill="#334155">"Sonbaharda yapraklar sarardı." ➔ Geçişsiz</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Edilgen çatılı tüm fiiller aynı zamanda GEÇİŞSİZDİR!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">3. TEMA: ERDEMLER — METİNDE ANLAM VE ANLATIM BİÇİMLERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">"Bir Somun Ekmekten Alınan Ders" ve Erdemler</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Ana Düşünce (Ana Fikir):</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#334155">Emek verilerek kazanılan helal lokmanın, kanaatkârlığın,</text>\n  <text x="180" y="132" text-anchor="middle" font-size="11" fill="#334155">şükretmenin ve paylaşmanın insana huzur vermesi.</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Bağlamdan Kelime Anlamı Tahmini (T.8.3.5):</text>\n  <text x="180" y="174" text-anchor="middle" font-size="11" fill="#334155">Somun (kabuğu gevrek, içi yumuşak yuvarlak ekmek),</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11" fill="#334155">kanaat (elindekiyle yetinme), erdem (fazilet, ahlaki iyilik),</text>\n  <text x="180" y="210" text-anchor="middle" font-size="11" fill="#334155">tevekkül, vefa ve diğerkâmlık (özgecilik).</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Anlatım Biçimleri ve Düşünceyi Geliştirme</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Öyküleyici Anlatım: Olay, yer, zaman ve kişi</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">unsurlarıyla okuyucuyu olayın içinde yaşatır.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Betimleyici Anlatım: Varlıkları sözcüklerle</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#334155">resmederek zihinde canlandırır (gözlem esastır).</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Açıklayıcı ve Tartışmacı Anlatım:</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#334155">Bilgi verir (açıklama) veya bir tezi savunup</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#334155">karşıt görüşü çürütür (tartışma).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
